    'market.sampleSub': { zh: '已采集 {n} 则广告，{d} 则有可用完整描述；职业排名按当前样本，职业与技能尚无可比的实测月度历史。', en: '{n} sampled ads, {d} usable descriptions. Careers ranked by current sample; comparable observed monthly career and skill history is not available.', ms: '{n} iklan sampel, {d} huraian boleh digunakan. Kerjaya disusun mengikut sampel semasa; sejarah cerapan bulanan kerjaya dan kemahiran yang setara belum tersedia.' },
    'market.sampleSkills': { zh: '技能提及率：以 {n} 则可用完整描述为分母，索引摘要不计入；尚无可比历史。', en: 'Skill mention share among {n} usable full descriptions. Index excerpts excluded; no comparable history yet.', ms: 'Bahagian sebutan kemahiran daripada {n} huraian penuh. Petikan indeks dikecualikan; sejarah belum tersedia.' },
    'market.sampleNote': { zh: '来源：{source}。展示最新本地采集样本；并非全国市场总量。Indeed 为未实时核实的索引记录；本列不是整月新增数。', en: 'Source: {source}. Latest local collection sample, not national totals. Indeed records are unverified index metadata; this column is not monthly new ads.', ms: 'Sumber: {source}. Sampel kutipan setempat terkini, bukan jumlah negara. Indeed ialah metadata indeks belum disahkan; lajur ini bukan iklan baharu bulanan.' },
    'market.sampleSkillReference': { zh: '技能热度为可用描述中的提及率；难度仍为参考等级。', en: 'Skill heat is mention share in usable descriptions; difficulty remains a reference level.', ms: 'Populariti ialah bahagian sebutan dalam huraian; kesukaran kekal tahap rujukan.' },
    'watch.sourceLabel': { zh: '招聘原始链接（LinkedIn / Indeed）', en: 'Original posting URL (LinkedIn / Indeed)', ms: 'URL iklan asal (LinkedIn / Indeed)' },
    'watch.sourceHelp': { zh: '填写链接可启用每日变更检查；首次成功读取建立基线。仅上传文字或文件无法定位原始广告。', en: 'Add a URL for daily change checks. First successful fetch establishes the baseline. Text or files alone cannot identify the original ad.', ms: 'Tambah URL untuk semakan harian. Bacaan pertama menetapkan garis dasar. Teks atau fail sahaja tidak mengenal pasti iklan asal.' },
    'watch.missing': { zh: '此 customise 岗位尚无原始招聘链接，无法自动追踪。', en: 'This customised role has no source URL and cannot be monitored yet.', ms: 'Jawatan tersuai ini tiada URL sumber dan belum boleh dipantau.' },
    'watch.attach': { zh: '启用岗位追踪', en: 'Track this posting', ms: 'Pantau iklan ini' },
    'watch.changed': { zh: '这家公司的招聘信息发生变化。当前路线仍保留，请查看最新内容并重新生成。', en: 'This company’s job posting changed. Your existing roadmap is preserved. Review the latest content and regenerate it.', ms: 'Iklan kerja syarikat ini berubah. Peta laluan lama dikekalkan. Semak kandungan terkini dan jana semula.' },
    'watch.tracking': { zh: '已登记岗位追踪；首次读取建立基线，之后由每日工作流检查。', en: 'Posting tracking registered. The first fetch establishes a baseline; the daily workflow checks subsequent changes.', ms: 'Pemantauan didaftarkan. Bacaan pertama menetapkan garis dasar; aliran harian menyemak perubahan.' },
    'watch.openSource': { zh: '查看原始招聘广告', en: 'Open original posting', ms: 'Buka iklan asal' },
    'watch.lastChecked': { zh: '最近检查：{at}', en: 'Last checked: {at}', ms: 'Semakan terakhir: {at}' },
    'watch.failed': { zh: '本次未能读取来源，保留原路线及上次检查结果。', en: 'Source could not be read; roadmap and previous results are preserved.', ms: 'Sumber tidak dapat dibaca; peta laluan dan hasil terdahulu dikekalkan.' },
    'watch.review': { zh: '查看最新招聘内容', en: 'Review latest job content', ms: 'Semak kandungan kerja terkini' },
    'watch.regenerate': { zh: '使用最新招聘要求重新生成', en: 'Regenerate with latest requirements', ms: 'Jana semula dengan keperluan terkini' },
    'error.posting-source-invalid': { zh: '请输入有效的 HTTPS 招聘链接。', en: 'Enter a valid HTTPS posting URL.', ms: 'Masukkan URL iklan HTTPS yang sah.' },
    'error.posting-source-unsupported': { zh: '目前支持 LinkedIn 的职位详情链接或 Indeed 的 viewjob?jk= 链接。', en: 'Use a LinkedIn job-detail URL or an Indeed viewjob?jk= URL.', ms: 'Gunakan URL butiran LinkedIn atau URL Indeed viewjob?jk=.' },
    'error.posting-changed-regenerate': { zh: '招聘要求已更新，请使用“使用最新招聘要求重新生成”。', en: 'Requirements changed. Choose regenerate with latest requirements.', ms: 'Keperluan berubah. Pilih jana semula dengan keperluan terkini.' },
    'error.posting-revision-stale': { zh: '招聘信息又有更新，请刷新后查看最新版本。', en: 'Posting changed again. Refresh and review the latest revision.', ms: 'Iklan berubah lagi. Muat semula untuk menyemak versi terkini.' },
