    // Project introduction in the home tab
    'home.navigation': { zh: '项目介绍', en: 'Project introduction', ms: 'Pengenalan projek' },
    'home.team': { zh: '由 {team} 团队打造', en: 'A project by {team}', ms: 'Projek oleh {team}' },
    'home.tagline': { zh: '探索职业方向，让每一次学习成为成长。', en: 'Explore your future. Grow one skill at a time.', ms: 'Terokai masa depan anda. Berkembang satu kemahiran demi satu.' },
    'home.intro': { zh: 'KerjayaKu 将 3D 世界探索、AI 职业规划与宠物养成结合，帮助你为下一份职业做好准备。', en: 'KerjayaKu combines 3D world exploration, AI-assisted career planning and virtual pets to help you prepare for your next career.', ms: 'KerjayaKu menggabungkan penerokaan dunia 3D, perancangan kerjaya berbantu AI dan haiwan maya untuk membantu anda bersedia bagi kerjaya seterusnya.' },
    'home.plan': { zh: '描述已有技能或上传简历，选择目标职业或提供招聘要求，再根据技能差距生成个人学习路线。', en: 'Describe your skills or upload a CV, choose a career or provide a target job posting, and generate a learning roadmap based on your skill gaps.', ms: 'Terangkan kemahiran anda atau muat naik CV, pilih kerjaya atau berikan iklan jawatan sasaran, kemudian jana peta laluan pembelajaran berdasarkan jurang kemahiran anda.' },
    'home.progress': { zh: '按照自己的节奏学习并记录练习，让投入转化为任务进度、积分，以及职业宠物所展现的成长。', en: 'Learn at your own pace and record your practice. Turn that effort into task progress, points and growth reflected in your career pet.', ms: 'Belajar mengikut rentak sendiri dan catat latihan anda. Usaha itu diterjemahkan kepada kemajuan tugasan, mata dan perkembangan yang dipaparkan melalui haiwan kerjaya anda.' },
    'home.journey': { zh: '了解技能 → 选择职业 → 制定路线 → 持续成长', en: 'Know your skills → Choose a career → Plan your path → Keep growing', ms: 'Kenali kemahiran → Pilih kerjaya → Rancang laluan → Terus berkembang' },

    // Project technical stack
    'stack.title': { zh: '技术栈', en: 'Technical stack', ms: 'Teknologi projek' },
    'stack.intro': { zh: 'KerjayaKu 的技术组成：从 3D 探索与职业规划，到聊天助手和岗位市场数据。', en: 'The technologies behind KerjayaKu: from 3D exploration and career planning to the chat companion and job-market data.', ms: 'Teknologi di sebalik KerjayaKu: daripada penerokaan 3D dan perancangan kerjaya kepada pembantu sembang dan data pasaran kerja.' },
    'stack.frontend': { zh: '原生 JavaScript 构建交互界面，HTML 与 Stylus 组织页面和样式，Vite 负责开发与打包。', en: 'Vanilla JavaScript powers the interface, HTML and Stylus define its layout and styles, and Vite handles development and builds.', ms: 'JavaScript membina antara muka, HTML dan Stylus menentukan susun atur serta gaya, dan Vite mengurus pembangunan serta binaan.' },
    'stack.world': { zh: 'Three.js 渲染 3D 世界，支持 WebGPU / WebGL；Rapier 处理角色移动和碰撞，GSAP 与 Howler 提供动画与音效。', en: 'Three.js renders the world with WebGPU / WebGL. Rapier handles character movement and collisions; GSAP and Howler support animation and audio.', ms: 'Three.js memaparkan dunia melalui WebGPU / WebGL. Rapier mengurus pergerakan dan perlanggaran; GSAP dan Howler menyokong animasi serta audio.' },
    'stack.backend': { zh: 'Node.js 提供游戏 API，处理技能档案、目标职业、学习路线与记录，并通过规则计算进度和积分。', en: 'The Node.js game API manages skill profiles, career targets, roadmaps and learning logs. Application rules calculate progress and points.', ms: 'API permainan Node.js mengurus profil kemahiran, sasaran kerjaya, peta laluan dan log pembelajaran. Peraturan aplikasi mengira kemajuan serta mata.' },
    'stack.botAI': { zh: '聊天助手可通过 Replit AI Integrations 接入所配置的 AI 模型，用于对话、消息分类和每日学习总结。', en: 'The chat companion can access its configured AI model through Replit AI Integrations for conversation, message classification and daily learning summaries.', ms: 'Pembantu sembang boleh mengakses model AI yang dikonfigurasi melalui Replit AI Integrations untuk perbualan, pengelasan mesej dan ringkasan pembelajaran harian.' },
    'stack.gameAI': { zh: '游戏后端通过 Anthropic SDK 调用 Claude，分析简历和岗位要求、生成学习路线并归类学习记录；支持结构化输出与演示模式。', en: 'The game backend uses the Anthropic SDK and Claude to analyze CVs and job requirements, generate roadmaps and classify learning logs, with structured outputs and a demo mode.', ms: 'Backend permainan menggunakan Anthropic SDK dan Claude untuk menganalisis CV serta keperluan jawatan, menjana peta laluan dan mengelaskan log pembelajaran, dengan output berstruktur serta mod demo.' },
    'stack.messaging': { zh: 'Python 与 FastAPI 构建独立聊天服务，接收 Telegram / WhatsApp Webhook，通过受 Token 保护的 API 向游戏提交学习汇报与总结。', en: 'A separate Python and FastAPI service handles Telegram / WhatsApp webhooks and submits learning reports and digests to the game through token-protected APIs.', ms: 'Perkhidmatan Python dan FastAPI berasingan mengendalikan webhook Telegram / WhatsApp serta menghantar laporan dan ringkasan pembelajaran ke permainan melalui API yang dilindungi token.' },
    'stack.market': { zh: 'n8n 工作流通过 JSearch / RapidAPI 获取马来西亚岗位样本，过滤、去重并按关键词统计技能需求，供游戏展示每周趋势。', en: 'An n8n workflow retrieves Malaysian job samples through JSearch / RapidAPI, filters and deduplicates them, then counts skill keywords for weekly market trends.', ms: 'Aliran kerja n8n mendapatkan sampel jawatan Malaysia melalui JSearch / RapidAPI, menapis dan membuang pendua, kemudian mengira kata kunci kemahiran untuk trend mingguan.' },
    'stack.storage': { zh: '游戏使用带版本与备份的 JSON 存档；聊天服务使用 SQLite 保存对话、学习汇报、消息去重和待确认状态。', en: 'The game uses versioned JSON saves with backups. The chat service uses SQLite for conversations, learning reports, message deduplication and pending confirmations.', ms: 'Permainan menggunakan simpanan JSON berversi dengan sandaran. Perkhidmatan sembang menggunakan SQLite untuk perbualan, laporan, pengesanan mesej pendua dan pengesahan tertunda.' },
    'stack.assets': { zh: 'Blender 与 Python 脚本制作角色骨骼、动作、职业宠物和场景，导出 GLB；Draco 与 KTX2 用于模型和纹理压缩。', en: 'Blender and Python scripts create rigs, animation, career pets and environments exported as GLB assets. Draco and KTX2 support model and texture compression.', ms: 'Blender dan skrip Python menghasilkan rig, animasi, haiwan kerjaya serta persekitaran yang dieksport sebagai GLB. Draco dan KTX2 menyokong pemampatan model serta tekstur.' },
    'stack.testing': { zh: 'Node 测试、Pytest 与 Playwright 验证业务规则、聊天接口和浏览器交互；项目包含 Replit 构建与部署配置。', en: 'Node tests, Pytest and Playwright verify application rules, chat integrations and browser interactions. The project includes Replit build and deployment configuration.', ms: 'Ujian Node, Pytest dan Playwright mengesahkan peraturan aplikasi, integrasi sembang serta interaksi pelayar. Projek menyertakan konfigurasi binaan dan penggunaan Replit.' },
    'stack.credit': { zh: '3D 世界基础改编自 Bruno Simon 的 Folio 2025（MIT 开源项目）。', en: 'The 3D foundation is adapted from Bruno Simon’s Folio 2025, an MIT-licensed open-source project.', ms: 'Asas 3D diadaptasi daripada Folio 2025 oleh Bruno Simon, projek sumber terbuka berlesen MIT.' },
    'stack.projectSource': { zh: '查看 Chill chill 项目源码', en: 'View the Chill chill project source', ms: 'Lihat kod sumber projek Chill chill' },
    'stack.upstreamSource': { zh: '原始开源项目', en: 'Original open-source project', ms: 'Projek sumber terbuka asal' },

