    // Guided tour by the wizard ghost (sources/Career/CareerTour.js): the player really goes through the system once
    'tutorial.label': { zh: '新手教学', en: 'Beginner tour', ms: 'Lawatan pemula' },
    'tutorial.replay': { zh: '重看新手教学', en: 'Replay the beginner tour', ms: 'Ulang lawatan pemula' },
    'tutorial.skip': { zh: '跳过教学', en: 'Skip tour', ms: 'Langkau' },
    'tutorial.next': { zh: '继续', en: 'Next', ms: 'Seterusnya' },
    'hint.pressEnter': { zh: '按 Enter ↵', en: 'Press Enter ↵', ms: 'Tekan Enter ↵' },
    'tutorial.finish': { zh: '开始冒险！', en: 'Start the adventure!', ms: 'Mulakan pengembaraan!' },
    'tutorial.waiting': { zh: '等你完成这一步…', en: 'Waiting for you to do it…', ms: 'Menunggu anda…' },
    'tutorial.demo': { zh: '教学中 AI 使用示例数据', en: 'AI uses demo data during the tour', ms: 'AI guna data demo semasa lawatan' },
    'tour.ghost': { zh: '小灵', en: 'Wisp', ms: 'Wisp' },
    'tour.intro.1': { zh: '嗨！我是小灵，这个世界的向导幽灵 👻', en: 'Hi! I am Wisp, the guide ghost of this world 👻', ms: 'Hai! Saya Wisp, hantu pemandu dunia ini 👻' },
    'tour.intro.2': { zh: '接下来我会带你真的走一轮：建立能力档案、选目标职业、领养职业宠物、生成学习路线、写下第一条学习记录。', en: 'I will walk you through the whole thing for real: build your skill profile, pick a target career, adopt a career pet, plan a roadmap and write your first study log.', ms: 'Saya akan bawa anda melalui semuanya: bina profil kemahiran, pilih kerjaya sasaran, ambil haiwan kerjaya, rancang peta laluan dan tulis log pembelajaran pertama.' },
    'tour.intro.3': { zh: '所有功能都在屏幕上方的菜单。我会让要点的按钮闪起来，你跟着点就好！', en: 'Everything lives in the menu at the top of the screen. I will make the button to press glow, just follow it!', ms: 'Semuanya ada dalam menu di bahagian atas skrin. Saya akan buat butang yang perlu ditekan bercahaya, ikut sahaja!' },
    'tour.profile.open': { zh: '第一步，点上方的「档案」。', en: 'Step one: click Profile at the top.', ms: 'Langkah pertama: klik Profil di atas.' },
    'tour.profile.fill': { zh: '在框里写下你学过、做过的事，例如「我学过 Python 和 SQL，做过一个网页项目」，再按「让 AI 整理技能」。也可以在下面直接输入技能，按「添加」。', en: 'Write what you have learned or done in the box, e.g. "I learned Python and SQL and built a website", then press Extract my skills. You can also type a skill below and press Add.', ms: 'Tulis apa yang anda pelajari atau lakukan, cth. "Saya belajar Python dan SQL dan membina laman web", kemudian tekan Ekstrak kemahiran saya. Anda juga boleh taip kemahiran di bawah dan tekan Tambah.' },
    'tour.profile.done': { zh: '很好！你的技能都记下来了，导师们会用它算你和每个职业的匹配度。', en: 'Nice! Your skills are saved, the mentors use them to work out how well you fit each career.', ms: 'Bagus! Kemahiran anda disimpan, mentor menggunakannya untuk mengira padanan anda dengan setiap kerjaya.' },
    'tour.careers.open': { zh: '接下来点上方的「职业」。', en: 'Next, click Careers at the top.', ms: 'Seterusnya, klik Kerjaya di atas.' },
    'tour.careers.pick': { zh: '用最上面的搜索框找一个你有兴趣的职业，点进去。选「一般模式」，再按下面的确认按钮设为目标。有招聘广告的话，也可以选「定制模式」上传。', en: 'Use the search box at the top to find a career you like and open it. Choose General mode, then press the confirm button to set it as your goal. Got a job posting? Customise mode lets you upload it.', ms: 'Gunakan kotak carian di atas untuk mencari kerjaya yang anda minati dan bukanya. Pilih mod Umum, kemudian tekan butang sahkan untuk menjadikannya matlamat. Ada iklan kerja? Mod Suai membolehkan anda memuat naiknya.' },
    'tour.careers.done': { zh: '目标设定好了：{career}！', en: 'Goal set: {career}!', ms: 'Matlamat ditetapkan: {career}!' },
    'tour.pet.open': { zh: '每个职业都有一只职业宠物，你的是 {pet}。点上方的「宠物」去看看它吧。', en: 'Every career comes with a career pet, yours is {pet}. Click Pet at the top to meet it.', ms: 'Setiap kerjaya ada haiwan kerjaya, milik anda ialah {pet}. Klik Haiwan di atas untuk berjumpa dengannya.' },
    'tour.pet.explain': { zh: '{pet} 的好感度会随着你完成路线任务、写学习记录而上升，它也会跟着你在世界里走。照顾好它哦！', en: '{pet}’s affinity grows as you clear roadmap tasks and log your study, and it follows you around the world. Take good care of it!', ms: 'Keakraban {pet} bertambah apabila anda menyelesaikan tugasan dan mencatat pembelajaran, dan ia mengikut anda di dunia ini. Jaga ia baik-baik!' },
    'tour.roadmap.open': { zh: '现在点上方的「路线」。', en: 'Now click Roadmap at the top.', ms: 'Sekarang klik Peta laluan di atas.' },
    'tour.roadmap.generate': { zh: '按「生成路线」，AI 会根据你和目标职业的差距，把学习分成几个阶段。（教学中用示例数据，所以很快）', en: 'Press Plan my roadmap: the AI splits your learning into stages from the gap between you and the goal. (The tour uses demo data, so it is quick.)', ms: 'Tekan Rancang peta laluan: AI membahagikan pembelajaran kepada beberapa peringkat berdasarkan jurang anda. (Lawatan guna data demo, jadi ia pantas.)' },
    'tour.roadmap.explain': { zh: '这张藏宝图就是你的路线！每面旗子是一个阶段，完成里面的任务就能往宝箱前进。', en: 'This treasure map is your roadmap! Each flag is a stage, clear its tasks to move toward the chest.', ms: 'Peta harta karun ini ialah peta laluan anda! Setiap bendera ialah satu peringkat, selesaikan tugasannya untuk mara ke peti harta.' },
    'tour.log.open': { zh: '最后一步：按右上角的 × 关掉地图，再点上方的「记录」。', en: 'Last step: close the map with the × at the top right, then click Log at the top.', ms: 'Langkah terakhir: tutup peta dengan × di kanan atas, kemudian klik Log di atas.' },
    'tour.log.write': { zh: '写下今天学了什么，例如「今天学了 2 小时{skill}，做了 5 道练习」，然后按「记录」。', en: 'Write what you studied today, e.g. "Studied {skill} for 2 hours and did 5 exercises", then press Log it.', ms: 'Tulis apa yang anda pelajari hari ini, cth. "Belajar {skill} selama 2 jam dan buat 5 latihan", kemudian tekan Log.' },
    'tour.log.done': { zh: '记录好了！AI 会把它对应到路线任务，路线往前推进，{pet} 的好感度也上升了。', en: 'Logged! The AI matches it to your roadmap tasks, the roadmap moves forward and {pet}’s affinity goes up.', ms: 'Direkodkan! AI memadankannya dengan tugasan peta laluan, peta laluan bergerak ke hadapan dan keakraban {pet} meningkat.' },
    'tour.outro.1': { zh: '你已经走完一整轮了 🎉 之后可以在世界里找职业导师聊天，看看排行榜，或者用 WASD 到处逛逛。', en: 'You made it through a full round 🎉 Next, chat with the career mentors around the world, check the leaderboard, or wander around with WASD.', ms: 'Anda telah melalui satu pusingan penuh 🎉 Seterusnya, berbual dengan mentor kerjaya, lihat papan markah, atau jelajah dengan WASD.' },
    'tour.outro.2': { zh: '想再看一次的话，在「设置」里按「重看新手教学」。下次见！', en: 'Want to see it again? Press Replay the beginner tour in Settings. See you!', ms: 'Mahu lihat lagi? Tekan Ulang lawatan pemula dalam Tetapan. Jumpa lagi!' },

