    // SDG (server/sdg.js)
    'sdg.title': { zh: '可持续发展目标（SDG）', en: 'Sustainable Development Goals', ms: 'Matlamat Pembangunan Mampan' },
    'sdg.intro': { zh: '每个职业和技能都对应联合国 17 个可持续发展目标中的具体指标。你为目标职业做的每一步准备，都在推动这些目标。', en: 'Every career and skill is tagged with specific targets of the 17 UN Sustainable Development Goals. Each step you prepare for your target career moves them.', ms: 'Setiap kerjaya dan kemahiran ditanda dengan sasaran khusus 17 Matlamat Pembangunan Mampan PBB. Setiap langkah persediaan anda untuk kerjaya sasaran menggerakkannya.' },
    'sdg.path': { zh: '你选择的「{career}」路线，目前对各目标的推动进度：', en: 'Your path to {career} and how far it moves each goal so far:', ms: 'Laluan anda ke {career} dan sejauh mana ia menggerakkan setiap matlamat setakat ini:' },
    'sdg.byCareer': { zh: '这个职业的日常工作直接推动', en: 'The job itself moves this goal', ms: 'Kerja ini sendiri menggerakkan matlamat ini' },
    'sdg.bySkills': { zh: '通过你学的技能推动', en: 'Moved through the skills you learn', ms: 'Digerakkan melalui kemahiran yang anda pelajari' },
    'sdg.byLearning': { zh: '学到就业所需的技能本身就在推动（SDG 4.4、8.5）', en: 'Learning skills for a decent job moves this itself (SDG 4.4, 8.5)', ms: 'Mempelajari kemahiran untuk pekerjaan wajar menggerakkannya sendiri (SDG 4.4, 8.5)' },
    'sdg.progressNote': { zh: '进度 = 你在相关技能上的准备程度（档案 + 路线任务 + 学习汇报），是估计值，不是对实际影响的测量。', en: 'Progress = how prepared you are on the related skills (profile + roadmap tasks + learning reports). It is an estimate, not a measure of real-world impact.', ms: 'Kemajuan = tahap persediaan anda dalam kemahiran berkaitan (profil + tugasan + laporan). Ia anggaran, bukan ukuran impak sebenar.' },
    'sdg.none': { zh: '还没有目标职业。先选一个职业，就能看到你的路线推动哪些目标。', en: 'No target career yet. Pick one to see which goals your path moves.', ms: 'Belum ada kerjaya sasaran. Pilih satu untuk melihat matlamat yang digerakkan laluan anda.' },
    'sdg.allTitle': { zh: '17 个目标', en: 'The 17 goals', ms: '17 matlamat' },
    'sdg.allHelp': { zh: '点一个目标，看看哪些职业在推动它。亮起的是你目前路线涉及的目标。', en: 'Click a goal to see the careers that move it. Highlighted goals are part of your current path.', ms: 'Klik satu matlamat untuk melihat kerjaya yang menggerakkannya. Matlamat yang diserlahkan ialah sebahagian laluan anda.' },
    'sdg.careerCount': { zh: '{n} 个职业', en: '{n} careers', ms: '{n} kerjaya' },
    'sdg.note': { zh: '职业与目标的对应由团队按 SDG 官方指标整理，AI 生成的新职业只能从同一份指标清单中选择。', en: 'Career-to-target links are curated by the team from the official SDG targets. AI-generated careers can only choose from the same list.', ms: 'Pautan kerjaya ke sasaran disusun oleh pasukan daripada sasaran SDG rasmi. Kerjaya janaan AI hanya boleh memilih daripada senarai yang sama.' },
    'sdg.source': { zh: '联合国 SDG 指标框架', en: 'UN SDG indicator framework', ms: 'Rangka kerja penunjuk SDG PBB' },
    'sdg.careerTitle': { zh: '这个职业如何推动 SDG', en: 'How this career moves the SDGs', ms: 'Bagaimana kerjaya ini menggerakkan SDG' },
    'sdg.careerNote': { zh: '对应的是联合国 SDG 的具体指标（例如 4.4），不是笼统的目标。', en: 'Each link is a specific UN SDG target (e.g. 4.4), not a loose association.', ms: 'Setiap pautan ialah sasaran SDG PBB yang khusus (cth. 4.4), bukan kaitan longgar.' },
    'sdg.fromSkills': { zh: '根据这个职业需要的技能推断。', en: 'Inferred from the skills this career needs.', ms: 'Disimpulkan daripada kemahiran yang diperlukan kerjaya ini.' },
    'sdg.filter': { zh: '按想贡献的 SDG 筛选：', en: 'Filter by the SDG you want to contribute to:', ms: 'Tapis mengikut SDG yang ingin anda sumbangkan:' },
    'sdg.filtered': { zh: '只显示推动 SDG {goal}「{name}」的职业，再点一次取消。', en: 'Showing careers that move SDG {goal} "{name}". Click again to clear.', ms: 'Memaparkan kerjaya yang menggerakkan SDG {goal} "{name}". Klik sekali lagi untuk kosongkan.' },
    'sdg.stage': { zh: '完成这阶段推动：', en: 'This stage moves:', ms: 'Peringkat ini menggerakkan:' },

