    'careers.skillsVs': { zh: '要求这项技能的职位占比（{period} 这周，共 {n} 个职位），箭头是较 {previous} 那周的变化，单位是百分点。', en: 'Share of postings asking for each skill (week of {period}, {n} postings); arrows show the change vs the week of {previous}, in percentage points.', ms: 'Peratus jawatan yang meminta setiap kemahiran (minggu {period}, {n} jawatan); anak panah ialah perubahan berbanding minggu {previous}, dalam mata peratusan.' },
    'careers.skillsFirst': { zh: '要求这项技能的职位占比（{period} 这周，共 {n} 个职位）。这是第一周的数据，下周一更新后会显示较上周的变化。', en: 'Share of postings asking for each skill (week of {period}, {n} postings). First week of data: the change vs the previous week shows after next Monday\'s update.', ms: 'Peratus jawatan yang meminta setiap kemahiran (minggu {period}, {n} jawatan). Minggu pertama data: perubahan berbanding minggu lepas dipaparkan selepas kemas kini Isnin depan.' },
