    'skill.difficulty': { zh: '难度（估计）', en: 'Difficulty (estimate)', ms: 'Kesukaran (anggaran)' },
    'market.reference.title': { zh: '去年参考：JobStreet 马来西亚 {n} 则职位，用和我们采集相同的规则分类', en: 'Last year reference: {n} JobStreet Malaysia postings, sorted with the same rules as our collection', ms: 'Rujukan tahun lalu: {n} iklan JobStreet Malaysia, diasingkan dengan peraturan yang sama seperti kutipan kami' },
    'market.reference.cell': { zh: '{n} 则，占当月 JobStreet 样本 {total} 则的 {p}%', en: '{n} of the {total} JobStreet postings that month ({p}%)', ms: '{n} daripada {total} iklan JobStreet bulan itu ({p}%)' },
    'market.reference.note': { zh: '标着 JobStreet 的月份来自 Hugging Face 的 JobStreet 数据集（{author}，许可证：{licence}），采集期间 {from} 到 {to}，共 {n} 则。格子是该职业占当月样本的比例，颜色深浅按这份数据单独计算，标 * 的月份不完整。来源和收集方式都和我们自己的采集不同，所以不互相比较。', en: 'Months marked JobStreet come from a JobStreet dataset on Hugging Face ({author}, licence: {licence}), collected {from} to {to}, {n} postings. Cells show the share of the sample of that month, on a colour scale of this dataset alone; months marked * are partial. Another source and collector than ours, so the two are not compared.', ms: 'Bulan bertanda JobStreet datang daripada set data JobStreet di Hugging Face ({author}, lesen: {licence}), dikutip {from} hingga {to}, {n} iklan. Petak menunjukkan bahagian sampel bulan itu, dengan skala warna tersendiri; bulan bertanda * tidak lengkap. Sumber dan pengumpul berbeza daripada kami, jadi tidak dibandingkan.' },
    'mycol.title': { zh: '官方紧缺职业名单（MyCOL）', en: 'Official critical occupations list (MyCOL)', ms: 'Senarai pekerjaan kritikal rasmi (MyCOL)' },
