    'mycol.notListedNote': { zh: '这一版没有列入这个职业（不代表需求下降）', en: 'This edition did not list the career (not a sign of decline)', ms: 'Edisi ini tidak menyenaraikan kerjaya ini (bukan tanda penurunan)' },
