    'market.yoy.title': { zh: 'JobStreet 同期（每年 {from} 到 {to}）占比的年度变化', en: 'Yearly change of the JobStreet share in the same window ({from} to {to} each year)', ms: 'Perubahan tahunan bahagian JobStreet dalam tempoh yang sama ({from} hingga {to} setiap tahun)' },
    'market.yoy.thin': { zh: '样本不足（任一年少于 30 则）', en: 'Too few postings (under 30 in a year)', ms: 'Iklan terlalu sedikit (kurang 30 setahun)' },
    'market.yoy.detail': { zh: '全国估计占比 {from} → {to}（{change}%），按 DOSM 职业结构加权', en: 'national estimate {from} → {to} ({change}%), weighted to the DOSM occupation structure', ms: 'anggaran nasional {from} → {to} ({change}%), diwajarkan mengikut struktur pekerjaan DOSM' },
    'market.yoy.note': { zh: '最后一列「24→25」比较 JobStreet 两年同一段日期，并像民调一样按 DOSM 官方的职业结构加权，代表全国的网上招聘（2024 年用 DOSM 2024 年第二季、2025 年用 2025 年第一季的结构）。± 是 95% 误差，差距在误差以内写「≈」。只供参考，不用来计算职业推荐。', en: 'The last column, 24→25, compares JobStreet in the same dates of both years, weighted like a poll to the official DOSM occupation structure so it stands for all online job ads (2024 to DOSM 2024 Q2, 2025 to 2025 Q1). ± is the 95% margin; ≈ means the change is within it. For reference only, not used to rank careers.', ms: 'Lajur terakhir, 24→25, membandingkan JobStreet pada tarikh yang sama dua tahun, diwajarkan seperti tinjauan pendapat mengikut struktur pekerjaan rasmi DOSM supaya mewakili semua iklan dalam talian (2024 mengikut DOSM S2 2024, 2025 mengikut S1 2025). ± ialah ralat 95%; ≈ bermaksud perubahan dalam julat itu. Sebagai rujukan sahaja, tidak digunakan untuk menyusun kerjaya.' },
    'careers.yoy': { zh: 'JobStreet 2024→2025（每年 {from} 到 {to}）：{arrow}', en: 'JobStreet 2024→2025 ({from} to {to} each year): {arrow}', ms: 'JobStreet 2024→2025 ({from} hingga {to} setiap tahun): {arrow}' },
