    'market.national.value': { zh: '全国估计：{p}%（±{m}，95% 误差），按 DOSM 职业结构加权', en: 'National estimate: {p}% (±{m}, 95% margin), weighted to the DOSM occupation structure', ms: 'Anggaran nasional: {p}% (±{m}, ralat 95%), diwajarkan mengikut struktur pekerjaan DOSM' },
